initial_code:
function vincularPrototipo(proto, propriedades) {
  // Crie um novo objeto herdando de proto e aplique propriedades
}

correct_answer:
function vincularPrototipo(proto, propriedades) {
  const obj = Object.create(proto);
  if (propriedades) {
    Object.assign(obj, propriedades);
  }
  return obj;
}

